class MyQueue:
    def __init__(self):
        self.stack = []

    def push(self, x: int) -> None:
        self.stack.append(x)

    def pop(self) -> int:
        temp = []
        while self.stack:
            temp.append(self.stack.pop())
        val = temp.pop()
        while temp:
            self.stack.append(temp.pop())
        return val

    def peek(self) -> int:
        val = self.pop()
        # Restore the peeked value at the bottom/front of the stack.
        temp = []
        while self.stack:
            temp.append(self.stack.pop())
        self.stack.append(val)
        while temp:
            self.stack.append(temp.pop())
        return val

    def empty(self) -> bool:
        return not self.stack

